static void write_output(const char *out_dir) {
	{
		char *path=file_path(out_dir,"out",".csv");
		FILE *f=fopen(path,"w");if(!f){perror(path);exit(1);}
		for(size_t i=0;i<rel_out_len;i++) {
			fprintf(f,"%lld",(long long)rel_out_data[i].c[0]);
			fputc('\n',f);
		}
		int failed=ferror(f);if(fclose(f)||failed){perror(path);exit(1);}free(path);
	}
}

