static void load_facts(const char *facts_dir) {
	{
		char *path=file_path(facts_dir,"edge",".facts");
		FILE *f=fopen(path,"r");
		if(!f && errno!=ENOENT){perror(path);exit(1);}
		if(f) {
			char *line=NULL;size_t capacity=0,line_no=0;ssize_t length;
			while((length=getline(&line,&capacity,f))>=0) {
				line_no++;if(length && line[length-1]=='\n')line[--length]=0;
				if(length && line[length-1]=='\r')line[--length]=0;
				if(memchr(line,0,(size_t)length))facts_error(path,line_no,"NUL byte in facts");
				char *cols[2];
				if(split_fields(line,cols,2)!=2)facts_error(path,line_no,"expected 2 columns");
				Tuple_rel_edge t;
				t.c[0]=parse_number(cols[0],path,line_no);
				t.c[1]=parse_number(cols[1],path,line_no);
				rel_edge_insert(t);
			}
			if(ferror(f)){perror(path);exit(1);}free(line);if(fclose(f)){perror(path);exit(1);}
		}free(path);
	}
	{
		char *path=file_path(facts_dir,"node",".facts");
		FILE *f=fopen(path,"r");
		if(!f && errno!=ENOENT){perror(path);exit(1);}
		if(f) {
			char *line=NULL;size_t capacity=0,line_no=0;ssize_t length;
			while((length=getline(&line,&capacity,f))>=0) {
				line_no++;if(length && line[length-1]=='\n')line[--length]=0;
				if(length && line[length-1]=='\r')line[--length]=0;
				if(memchr(line,0,(size_t)length))facts_error(path,line_no,"NUL byte in facts");
				char *cols[1];
				if(split_fields(line,cols,1)!=1)facts_error(path,line_no,"expected 1 columns");
				Tuple_rel_node t;
				t.c[0]=parse_number(cols[0],path,line_no);
				rel_node_insert(t);
			}
			if(ferror(f)){perror(path);exit(1);}free(line);if(fclose(f)){perror(path);exit(1);}
		}free(path);
	}
}

